import React, { useRef } from 'react';
import NavBar from '../../components/NavBar';
import Footer from '../components/Footer';

const Sleeve = () => {
  const sections = {
    puff: useRef(null),
    bishop: useRef(null),
    bell: useRef(null),
    raglan: useRef(null),
    offShoulder: useRef(null),
  };

  const handleScroll = (event) => {
    const selected = event.target.value;
    if (sections[selected]) {
      sections[selected].current.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <>
      <NavBar />
      <div style={{ padding: '20px', textAlign: 'center' }}>
        <h1>Sleeve Varieties</h1>
        <select onChange={handleScroll} defaultValue="">
          <option value="" disabled>Select Sleeve Variety</option>
          <option value="puff">Puff Sleeve</option>
          <option value="bishop">Bishop Sleeve</option>
          <option value="bell">Bell Sleeve</option>
          <option value="raglan">Raglan Sleeve</option>
          <option value="offShoulder">Off Shoulder Sleeve</option>
        </select>
      </div>

      <div style={{ padding: '20px' }}>
        {/* Puff Sleeve Section */}
        <section ref={sections.puff} id="puff" style={{ marginBottom: '50px' }}>
          <h2>Puff Sleeve</h2>
          <img src="/Images/Designs/sleeves/puff-sleeve.jpg" alt="Puff Sleeve Design" style={{ width: '300px' }} />
          <p>Description and details about Puff Sleeves.</p>
        </section>

        {/* Bishop Sleeve Section */}
        <section ref={sections.bishop} id="bishop" style={{ marginBottom: '50px' }}>
          <h2>Bishop Sleeve</h2>
          <img src="/Images/Designs/sleeves/bishop-sleeve.jpg" alt="Bishop Sleeve Design" style={{ width: '300px' }} />
          <p>Description and details about Bishop Sleeves.</p>
        </section>

        {/* Bell Sleeve Section */}
        <section ref={sections.bell} id="bell" style={{ marginBottom: '50px' }}>
          <h2>Bell Sleeve</h2>
          <img src="/Images/Designs/sleeves/bell-sleeve.jpg" alt="Bell Sleeve Design" style={{ width: '300px' }} />
          <p>Description and details about Bell Sleeves.</p>
        </section>

        {/* Raglan Sleeve Section */}
        <section ref={sections.raglan} id="raglan" style={{ marginBottom: '50px' }}>
          <h2>Raglan Sleeve</h2>
          <img src="/Images/Designs/sleeves/raglan-sleeve.jpg" alt="Raglan Sleeve Design" style={{ width: '300px' }} />
          <p>Description and details about Raglan Sleeves.</p>
        </section>

        {/* Off Shoulder Sleeve Section */}
        <section ref={sections.offShoulder} id="offShoulder" style={{ marginBottom: '50px' }}>
          <h2>Off Shoulder Sleeve</h2>
          <img src="/Images/Designs/sleeves/off-shoulder.jpg" alt="Off Shoulder Sleeve Design" style={{ width: '300px' }} />
          <p>Description and details about Off Shoulder Sleeves.</p>
        </section>
      </div>

      <Footer />
    </>
  );
};

export default Sleeve;
